module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

always @(*) begin
    case (in)
        4'b1111: code = 2'b11; // 7 (but typically 4'b1111 -> 3, but let's do standard priority)
        4'b0XXX: code = 2'b00; // Assuming XXX means don't care, but standard is highest index active
        4'b1xxx: code = 2'b10; // bit 3 active
        4'b?001: code = 2'b01; // bit 2 active (if lower bits are also high, this case is not reached due to priority)
        4'b??01: code = 2'b01; // bit 2 active
        4'b???1: code = 2'b01; // bit 2 active
        4'b????: code = 2'b00; // bit 1 active? No, let's re-do standard.
    endcase
end

// Actually, let's use a clearer priority approach:

always @(*) begin
    code = 2'b00; // default
    if (in[3]) code = 2'b11; // Let's assume indices: 3,2,1,0 -> outputs 2'b10, 2'b01, 2'b00? Or 3,1,0,2?
    // Standard is usually: 3->11, 2->10, 1->01, 0->00 but that's 2-bit for 4 inputs? Actually 2 bits can only represent 0 to 3.
    // So if we have 4 inputs, we need to consider which input is the highest active.
    // Let's define: in[3] is highest priority, then in[2], in[1], in[0].
    // If in[3] is 1, output 2'b11 (which would be 3 in decimal, but we only have 2 bits, so max is 3).
    // But 2 bits can represent 00,01,10,11 -> 0,1,2,3. So we can map:
    // in[3] -> 3 (11)
    // in[2] -> 2 (10)
    // in[1] -> 1 (01)
    // in[0] -> 0 (00)
    // And if multiple are 1, the highest index wins.

    // So better to write:
    if (in[3]) code = 2'b11;
    else if (in[2]) code = 2'b10;
    else if (in[1]) code = 2'b01;
    else if (in[0]) code = 2'b00;
    else code = 2'b00; // All zero, output zero
end

endmodule

