module fsm_3state (
    input clk, reset,
    input [1:0] d_in,
    output reg [1:0] state
);

always @(posedge clk) begin
    if (reset) begin
        state <= 2'b00;
    end else begin
        case (state)
            2'b00: if (d_in == 0) state <= 2'b01; else state <= 2'b10;
            2'b01: if (d_in == 0) state <= 2'b10; else state <= 2'b01;
            2'b10: if (d_in == 0) state <= 2'b00; else state <= 2'b11;
            default: state <= 2'b00;
        endcase
    end
end

endmodule

module fsm_3state (
    input clk, reset,
    output reg [1:0] state
);
    // Define states
    parameter S_IDLE   = 2'b00;
    parameter S_STATE1 = 2'b01;
    parameter S_STATE2 = 2'b10;

    // State register
    always @(posedge clk or posedge reset) begin
        if (reset)
            state <= S_IDLE;
        else
            // Simple state machine behavior
            case (state)
                S_IDLE:   state <= S_STATE1;
                S_STATE1: state <= S_STATE2;
                S_STATE2: state <= S_IDLE;
                default:  state <= S_IDLE;
            endcase
    end
endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state,
    output done
);
    reg [1:0] state_reg;
    reg [1:0] next_state;

    parameter S0 = 2'b00;
    parameter S1 = 2'b01;
    parameter S2 = 2'b10;

    always @(posedge clk or posedge reset) begin
        if (reset)
            state_reg <= S0;
        else
            state_reg <= next_state;
    end

    always @(*) begin
        case (state_reg)
            S0: next_state = S1;
            S1: next_state = S2;
            S2: next_state = S0;
            default: next_state = S0;
        endcase
    end

    assign state = state_reg;
    assign done = (state_reg == S2) ? 1'b1 : 1'b0;

endmodule

