    parameter STATE_RED = 3'b000;
    parameter STATE_GREEN = 3'b001;
    parameter STATE_YIELD = 3'b010;

    reg [2:0] current_state;
    reg [2:0] next_state;

    // State Transition Logic
    always @(*) begin
        next_state = current_state;
        case (current_state)
            STATE_RED: next_state = STATE_GREEN;
            STATE_GREEN: next_state = STATE_YIELD;
            STATE_YIELD: next_state = STATE_RED;
            default: next_state = STATE_RED;
        endcase
    end

    // State Register
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= STATE_RED;
        end else begin
            current_state <= next_state;
        end
    end

    // Output Logic: Map states to light colors
    assign light = current_state;

