module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    reg [1:0] state_reg;

    // State encoding:
    // 0: Idle / Ground
    // 1: Moving Up
    // 2: Moving Down
    // 3: Top Floor

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state_reg <= 2'b00;
        end else begin
            case (state_reg)
                2'b00: if (up_request) state_reg <= 2'b01;
                       else state_reg <= 2'b00;
                2'b01: if (!up_request) state_reg <= 2'b10;
                       else state_reg <= 2'b01;
                2'b10: if (up_request) state_reg <= 2'b01;
                       else state_reg <= 2'b00;
                2'b11: state_reg <= 2'b11;
                default: state_reg <= 2'b00;
            endcase
        end
    end

    assign state = state_reg;

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);
    reg [1:0] current_state = 2'b00;
    reg [1:0] next_state;

    // State encoding
    // 2'b00: Idle
    // 2'b01: Going Up
    // 2'b10: Going Down
    // 2'b11: Stopped (optional)

    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= 2'b00;
        else
            current_state <= next_state;
    end

    always @(*) begin
        case (current_state)
            2'b00: begin // Idle
                if (up_request)
                    next_state = 2'b01;
                else if (down_request)
                    next_state = 2'b10;
                else
                    next_state = 2'b00;
            end
            2'b01: next_state = 2'b00; // Return to idle after moving up
            2'b10: next_state = 2'b00; // Return to idle after moving down
            default: next_state = 2'b00;
        endcase
    end

    assign state = current_state;

endmodule

