module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    // Define states using 2 bits
    parameter IDLE = 2'b00;
    parameter COIN_INSERTED = 2'b01;
    parameter ITEM_SELECTED = 2'b10;
    parameter DISPENSING = 2'b11;

    reg [1:0] current_state;
    reg [1:0] next_state;

    // Combinational logic for next state
    always @(*) begin
        case (current_state)
            IDLE:
                if (coin_inserted)
                    next_state = COIN_INSERTED;
                else
                    next_state = IDLE;

            COIN_INSERTED:
                if (item_selected)
                    next_state = ITEM_SELECTED;
                else
                    next_state = COIN_INSERTED;

            ITEM_SELECTED:
                if (coin_inserted) // Assuming re-insertion required for dispense
                    next_state = DISPENSING;
                else
                    next_state = ITEMS_SELECTED; // Assuming error or repeat

            DISPENSING:
                next_state = IDLE; // Or some ready state

            default:
                next_state = IDLE;
        endcase
    end

    // Sequential logic for state register
    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    // Output assignment
    assign state = current_state;

endmodule

