module log2_int (
    input signed [15:0] in_0,
    output signed [7:0] out
);

    always @(*) begin
        if (in_0 == 0) begin
            out = 0;
        end
        else if (in_0 == 1) begin
            out = 0;
        end
        else if (in_0 <= 2) begin
            out = 1;
        end
        else if (in_0 <= 4) begin
            out = 2;
        end
        else if (in_0 <= 8) begin
            out = 3;
        end
        else if (in_0 <= 16) begin
            out = 4;
        end
        else if (in_0 <= 32) begin
            out = 5;
        end
        else if (in_0 <= 64) begin
            out = 6;
        end
        else if (in_0 <= 128) begin
            out = 7;
        end
        else if (in_0 <= 256) begin
            out = 8;
        end
        else if (in_0 <= 512) begin
            out = 9;
        end
        else if (in_0 <= 1024) begin
            out = 10;
        end
        else if (in_0 <= 2048) begin
            out = 11;
