    input start,
    output reg [7:0] data_out
);
    // S-box lookup table
    reg [3:0] sbox;
    generate
        for (genvar i = 0; i < 16; i = i + 1) begin : sbox_gen
            assign sbox[i] = 4'b{
                i[0] ? 1'b1 : 1'b0,
                i[3],
                i[1] ? 1'b1 : 1'b0,
                i[2]
            };
        end
    endgenerate

    // Key schedule
    reg [3:0] key_reg;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            key_reg <= {4'b0000};
        end else if (start) begin
            key_reg <= key;
        end
    end

    // XOR key with data
    wire [7:0] xored_data = data_in ^ key_reg;

    // Simple substitution using S-box
    wire [3:0] sub_data = sbox[xored_data[3:0]];
    wire [3:0] sub_nib = sbox[xored_data[7:4]];

    // Output construction
    assign data_out = {sub_nib, sub_data};

endmodule

