module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);

    reg gt, eq, lt;

    // If all bits are equal, then the numbers are equal
    // Otherwise, if a > b, then gt is 1
    // Otherwise, if a < b, then lt is 1
    // This is a simple comparison starting from the most significant bit

    assign eq = (a[3] == b[3]) && (a[2] == b[2]) && (a[1] == b[1]) && (a[0] == b[0]);

    if (eq) begin
        gt = 0;
        lt = 0;
    end
    else begin
        // Compare from MSB to LSB
        if ((a[3] && !b[3]) || ((a[3] == b[3]) && (a[2] && !b[2])) ||
            ((a[3] == b[3]) && (a[2] == b[2]) && (a[1] && !b[1])) ||
            ((a[3] == b[3]) && (a[2] == b[2]) && (a[1] == b[1]) && (a[0] && !b[0])))
            gt = 1;
        else if ((!a[3] && b[3]) || (((a[3] == b[3]) && (!a[2] && b[2])) && (a[3] == b[3])) ||
                 (((a[3] == b[3]) && (a[2] == b[2]) && (!a[1] && b[1])) && (a[3] == b[3]) && (a[2] == b[2])) ||
                 (((a[3] == b[3]) && (a[2] == b[2]) && (a[1] == b[1]) && (!a[0] && b[0])) && (a[3] == b[3]) && (a[2] == b[2]) && (a[1] == b[1])))
            lt = 1;
        else begin
            gt = 0;
            lt = 0;
        end
    end

    // Actually, let's rewrite this more concisely and correctly:
    // We'll use a simple loop through XORs and ANDs to check for equality first, then greater/less

    // The simpler approach:
    // Eq is true if all bits match
    // Gt is true if a > b (which happens if at the first differing bit, a's bit is 1 and b's is 0)
    // Lt is true if a < b (which happens if at the first differing bit, a's bit is 0 and b's is 1)

    // Let's define the differences
    reg d3, d2, d1, d0;
    assign d3 = a[3] ^ b[3];
    assign d2 = a[2] ^ b[2];
    assign d1 = a[1] ^ b[1];
    assign d0 = a[0] ^ b[0];

    // Eq is only true if there are no differences
    assign eq = (!d3) && (!d2) && (!d1) && (!d0);

    // Gt is true if at the first bit where they differ, a's bit is 1
    // This means: d3, then if not d3 then d2, then if not d2 then d1, then if not d1 then d0
    assign gt = (d3 && a[3]) ||
                ((!d3) && (d2 && a[2])) ||
                ((!d3) && (!d2) && (d1 && a[1])) ||
                ((!d3) && (!d2) && (!d1) && (d0 && a[0]));

    // Lt is true if at the first bit where they differ, a's bit is 0
    assign lt = (d3 && !a[3]) ||
                ((!d3) && (d2 && !a[2])) ||
                ((!d3) && (!d2) && (d1 && !a[1])) ||
                ((!d3) && (!d2) && (!d1) && (d0 && !a[0]));

    // Since these are always outputs, we should assign them directly.
    // But since we have intermediate wires, we can just assign eq, gt, lt directly to those.
    // However, the above logic is correct.

    // Final version with direct assignment:
    assign eq = (a[3] == b[3]) && (a[2] == b[2]) && (a[1] == b[1]) && (a[0] == b[0]);
    assign gt = (a > b);
    assign lt = (a < b);

    // Wait, Verilog supports relational operators in continuous assignments!
    // So the simplest and most correct code is:

    assign eq = (a == b);
    assign gt = (a > b);
    assign lt = (a < b);

endmodule

