module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

  // Define states
  parameter IDLE        = 2'b00;
  parameter TRAIN_ON    = 2'b01;
  parameter TRAIN_OFF   = 2'b10;
  parameter TRAIN_CYCLE = 2'b11;

  // Output register (assuming state itself is the output)
  logic [1:0] next_state;

  always @(posedge clk or posedge areset) begin
    if (areset) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  // State transition logic
  always @(*) begin
    case (state)
      IDLE: begin
        if (train_valid) begin
          next_state = TRAIN_ON;
        end else begin
          next_state = IDLE;
        end
      end
      TRAIN_ON: begin
        if (train_taken) begin
          next_state = TRAIN_OFF;
        end else begin
          next_state = IDLE;
        end
      end
      TRAIN_OFF: begin
        next_state = IDLE;
      end
      TRAIN_CYCLE: begin
        next_state = IDLE;
      end
      default: next_state = IDLE;
    endcase
  end

endmodule

