module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

  reg [3:0] state_cnt;
  reg state, next_state;
  reg temp_data;
  reg [2:0] state_register;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
      state_register <= 3'd0;
    else
      state_register <= state_cnt;
  end

  always @(*) begin
    next_state = state_register;
    case (state_register)
      3'd0: next_state = data_in ? 3'd1 : 3'd2;
      3'd1: next_state = data_in ? 3'd2 : 3'd1;
      3'd2: next_state = data_in ? 3'd2 : 3'd3;
      3'd3: next_state = data_in ? 3'd2 : 3'd2;
      default: next_state = 3'd0;
    endcase
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
      state <= 0;
    else
      state <= next_state;
  end

  assign sequence_detected = (state == 0);

endmodule

