module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

    // Internal signals
    reg [2:0] seq_state;           // Current state
    reg [2:0] next_state;         // Next state
    wire  seq_detected;           // Output of FSM

    // State encoding
    parameter IDLE = 3'd0;
    parameter RX1  = 3'd1;         // First '1' received
    parameter RX2  = 3'd2;         // '0' received after '1'
    parameter RX3  = 3'd3;         // '1' received after '0' (end of seq)

    // Output generation
    assign sequence_detected = (seq_state == RX3);

    // Next state logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            next_state <= IDLE;
        end else begin
            if (state == IDLE) begin
                if (data_in) next_state <= RX1;
                else         next_state <= IDLE;
            end else if (state == RX1) begin
                if (~data_in) next_state <= RX2;
                else         next_state <= RX1;
            end else if (state == RX2) begin
                if (data_in)  next_state <= RX3;
                else         next_state <= IDLE;
            end else if (state == RX3) begin
                if (data_in)  next_state <= RX1;
                else         next_state <= IDLE;
            end
        end
    end

    // Output assignment
    assign state = next_state;

endmodule
